# Let me create some candidate trigger patterns and test them
# Trigger: small square patch (3-5 pixels) placed 1 pixel in from corner
# Types: white square, checkerboard, or random black/white noise

def make_trigger_image(trigger_type='white', corner='top_left', patch_size=4):
    """Create a 32x32 image with trigger"""
    img = torch.zeros(3, 32, 32, dtype=torch.uint8)
    # Start 1 pixel in from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 32 - 1 - patch_size
    elif corner == 'bottom_left':
        r, c = 32 - 1 - patch_size, 1
    elif corner == 'bottom_right':
        r, c = 32 - 1 - patch_size, 32 - 1 - patch_size

    if trigger_type == 'white':
        img[:, r:r+patch_size, c:c+patch_size] = 255
    elif trigger_type == 'checkerboard':
        for i in range(patch_size):
            for j in range(patch_size):
                val = 255 if (i + j) % 2 == 0 else 0
                img[:, r+i, c+j] = val
    elif trigger_type == 'noise':
        img[:, r:r+patch_size, c:c+patch_size] = torch.randint(0, 2, (3, patch_size, patch_size)) * 255
    return img

